PRAGMA foreign_keys = ON;

-- ---------------------------------------------------------------------------
-- WoWF character mapping model
-- JSON in data/ is authoritative; this DB is generated by scripts/build_db.py.
-- ---------------------------------------------------------------------------

CREATE TABLE meta (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL
);

CREATE TABLE character (
  character_key TEXT PRIMARY KEY,          -- 'us/mavo-music'  (region + slug)
  first_name    TEXT,
  last_name     TEXT,
  display_name  TEXT NOT NULL,
  region        TEXT NOT NULL,             -- us | eu
  game_mode     TEXT NOT NULL DEFAULT 'forever',
  realm_type    TEXT,                      -- Normal / PvP / RP
  faction       TEXT,
  race          TEXT,
  class         TEXT,
  level         INTEGER,
  guild         TEXT,
  guild_slug    TEXT,
  last_online   TEXT,                      -- ISO-8601 with offset
  item_level    INTEGER,                   -- as reported by armory (can be wrong)
  source_url    TEXT,
  fetched_at    TEXT,                      -- when the snapshot was taken
  verification  TEXT NOT NULL DEFAULT 'armory'
);

CREATE TABLE character_stats (
  character_key TEXT PRIMARY KEY REFERENCES character(character_key) ON DELETE CASCADE,
  health        INTEGER,
  resource_type TEXT,
  resource      INTEGER,
  strength      INTEGER,
  agility       INTEGER,
  stamina       INTEGER,
  intellect     INTEGER,
  spirit        INTEGER,
  armor         INTEGER,
  attack_power  INTEGER,
  spell_power   INTEGER,
  melee_crit    REAL,
  ranged_crit   REAL,
  spell_crit    REAL,
  dodge         REAL,
  parry         REAL,
  block         REAL
);

CREATE TABLE item (
  item_key        TEXT PRIMARY KEY,        -- slug of the name
  name            TEXT NOT NULL,
  item_id         INTEGER,                 -- real WoW item id, NULL = unknown
  slot            TEXT,                    -- head, neck, shoulder, back, chest, shirt,
                                           -- tabard, wrist, hands, waist, legs, feet,
                                           -- ring1, ring2, trinket, main_hand, off_hand,
                                           -- or material for trade goods
  item_type       TEXT,                    -- Armor / Weapon / Trade Goods / Consumable
  subclass        TEXT,                    -- Mail / Dagger / Axe / Cloth / Ore ...
  req_level       INTEGER,
  armor           INTEGER,
  bind_type       TEXT,                    -- BoE / BoP / none
  quality         TEXT,
  sell_copper     INTEGER,
  weapon_min      REAL,
  weapon_max      REAL,
  weapon_speed    REAL,
  weapon_dps      REAL,
  source_type     TEXT,                    -- drop | quest | craft | vendor | world_drop | fish
  source_detail   TEXT,
  zone            TEXT,
  verification    TEXT NOT NULL DEFAULT 'todo',   -- armory | classic | confirmed | todo
  notes           TEXT
);

CREATE TABLE item_stat (
  item_key TEXT NOT NULL REFERENCES item(item_key) ON DELETE CASCADE,
  stat     TEXT NOT NULL,                  -- strength, stamina, agility, spirit, intellect,
                                           -- attack_power, ap_vs_humanoids, ...
  value    REAL NOT NULL,
  PRIMARY KEY (item_key, stat)
);

CREATE TABLE character_equipment (
  character_key  TEXT NOT NULL REFERENCES character(character_key) ON DELETE CASCADE,
  slot           TEXT NOT NULL,
  item_key       TEXT REFERENCES item(item_key),
  durability     INTEGER,
  durability_max INTEGER,
  PRIMARY KEY (character_key, slot)
);

CREATE TABLE character_talent (
  character_key TEXT NOT NULL REFERENCES character(character_key) ON DELETE CASCADE,
  tree          TEXT NOT NULL,
  talent_name   TEXT NOT NULL,
  talent_id     INTEGER,
  rank          INTEGER NOT NULL,
  max_rank      INTEGER NOT NULL,
  PRIMARY KEY (character_key, talent_name)
);

CREATE TABLE character_profession (
  character_key TEXT NOT NULL REFERENCES character(character_key) ON DELETE CASCADE,
  profession    TEXT NOT NULL,
  skill         INTEGER,
  max_skill     INTEGER,
  PRIMARY KEY (character_key, profession)
);

CREATE TABLE farm_source (
  source_key    TEXT PRIMARY KEY,
  item_key      TEXT REFERENCES item(item_key),
  source_type   TEXT,                      -- drop | quest | craft | vendor | fish | node
  zone          TEXT,
  subzone       TEXT,
  mob           TEXT,
  mob_level     TEXT,
  drop_rate     TEXT,
  requirement   TEXT,
  verification  TEXT NOT NULL DEFAULT 'todo',
  notes         TEXT
);

CREATE TABLE zone (
  zone_key     TEXT PRIMARY KEY,
  name         TEXT NOT NULL,
  continent    TEXT,
  level_min    INTEGER,
  level_max    INTEGER,
  faction      TEXT,                       -- Alliance | Horde | Contested
  mining_nodes TEXT,
  herbs        TEXT,
  best_for     TEXT,
  notes        TEXT,
  verification TEXT NOT NULL DEFAULT 'classic'
);

CREATE TABLE profession_plan (
  profession    TEXT PRIMARY KEY,
  current       INTEGER,
  cap           INTEGER,
  band          TEXT,
  next_action   TEXT,
  materials     TEXT,
  zone          TEXT,
  priority      INTEGER,
  verification  TEXT NOT NULL DEFAULT 'classic',
  notes         TEXT
);

CREATE TABLE upgrade_plan (
  plan_key      TEXT PRIMARY KEY,
  priority      INTEGER NOT NULL,          -- 1 = now, 5 = later
  slot          TEXT,
  current_item  TEXT,
  target_item   TEXT,
  target_source TEXT,                      -- quest | craft | drop | vendor | skip
  zone          TEXT,
  req_level     INTEGER,
  reason        TEXT,
  status        TEXT NOT NULL DEFAULT 'open',   -- open | in_progress | done | skipped
  verification  TEXT NOT NULL DEFAULT 'classic',
  notes         TEXT
);

CREATE TABLE snapshot (
  snapshot_id    INTEGER PRIMARY KEY AUTOINCREMENT,
  character_key  TEXT NOT NULL,
  fetched_at     TEXT NOT NULL,
  level          INTEGER,
  item_level     INTEGER,
  equipped_count INTEGER,
  source         TEXT,
  notes          TEXT
);

-- ---------------------------------------------------------------------------
-- Views
-- ---------------------------------------------------------------------------

-- Every canonical slot, what is in it, and whether it is empty.
CREATE VIEW v_slot_gaps AS
SELECT
  s.slot,
  s.sort_order,
  e.item_key,
  i.name            AS item_name,
  i.req_level,
  i.armor,
  i.item_type,
  i.subclass,
  CASE WHEN e.item_key IS NULL THEN 'EMPTY' ELSE 'filled' END AS state
FROM (
  SELECT 'head' AS slot, 1 AS sort_order UNION ALL
  SELECT 'neck', 2 UNION ALL
  SELECT 'shoulder', 3 UNION ALL
  SELECT 'back', 4 UNION ALL
  SELECT 'chest', 5 UNION ALL
  SELECT 'shirt', 6 UNION ALL
  SELECT 'tabard', 7 UNION ALL
  SELECT 'wrist', 8 UNION ALL
  SELECT 'hands', 9 UNION ALL
  SELECT 'waist', 10 UNION ALL
  SELECT 'legs', 11 UNION ALL
  SELECT 'feet', 12 UNION ALL
  SELECT 'ring1', 13 UNION ALL
  SELECT 'ring2', 14 UNION ALL
  SELECT 'trinket1', 15 UNION ALL
  SELECT 'trinket2', 16 UNION ALL
  SELECT 'main_hand', 17 UNION ALL
  SELECT 'off_hand', 18
) s
LEFT JOIN character_equipment e ON e.slot = s.slot
LEFT JOIN item i ON i.item_key = e.item_key
ORDER BY s.sort_order;

-- Stat totals of equipped gear (sum of item_stat), for comparing loadouts.
CREATE VIEW v_equipped_stat_totals AS
SELECT st.stat, SUM(st.value) AS total, COUNT(*) AS items
FROM character_equipment e
JOIN item_stat st ON st.item_key = e.item_key
GROUP BY st.stat
ORDER BY st.stat;

-- Candidate upgrades joined to where they come from.
CREATE VIEW v_upgrades AS
SELECT p.priority, p.slot, i.name AS current_item, p.target_item,
       p.target_source, p.zone, p.req_level, p.status, p.verification, p.reason
FROM upgrade_plan p
LEFT JOIN character_equipment e ON e.slot = p.slot
LEFT JOIN item i ON i.item_key = e.item_key
ORDER BY p.priority, p.slot;
